Defensively wrap the file reading operation in a try-except block to handle unreadable files or I/O failures gracefully [GENERAL_RULES]. Additionally, make the regex parsing in `extract_job` and `extract_step` more robust by supporting optional quotes around names, trailing whitespace, and carriage returns (`\r\n`).

```python
def read_workflow() -> str | None:
    try:
        return WORKFLOW_PATH.read_text(encoding="utf-8")
    except Exception:
        return None


def extract_job(workflow: str | None, job_name: str) -> str:
    if not workflow:
        raise AssertionError("Workflow content is empty or could not be read.")
    match = re.search(
        rf"(?ms)^  ['\"]?{re.escape(job_name)}['\"]?:\s*\n(?P<body>.*?)(?=^  [A-Za-z0-9_-]+:\s*\n|\Z)",
        workflow,
    )
    if match is None:
        raise AssertionError(f"Missing workflow job: {job_name}")
    return match.group("body")


def extract_step(job: str, step_name: str) -> str:
    match = re.search(
        rf"(?ms)^      - name: ['\"]?{re.escape(step_name)}['\"]?\s*\n(?P<body>.*?)(?=^      - |\Z)",
        job,
    )
    if match is None:
        raise AssertionError(f"Missing workflow step: {step_name}")
    return match.group("body")
```

